// CDLKICKINGBYLENGTHLookback returns how many leading bars
// [Core.CDLKICKINGBYLENGTH] consumes before its first value: called with
// startIdx 0, its first value is at that bar.
func (c *Core) CDLKICKINGBYLENGTHLookback() (int, error) {
	lookback := c.cdlkickingbylengthLookback()
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

// CDLKICKINGBYLENGTHDisplayShift returns how many bars ahead (positive) or
// behind (negative) of the bar that computed it a chart draws output outputIdx
// of [Core.CDLKICKINGBYLENGTH]. The values are never shifted.
//
// Every output of this function is drawn at its own bar, so the answer is 0.
//
// It takes the output's position among the outputs of
// [Core.CDLKICKINGBYLENGTH], from 0, and returns [BadParam] for an index that
// names no output.
func (c *Core) CDLKICKINGBYLENGTHDisplayShift(outputIdx int) (int, error) {
	if outputIdx < 0 || outputIdx >= 1 {
		return 0, BadParam
	}
	return 0, nil
}

// CDLKICKINGBYLENGTH recognizes the Kicking - bull/bear determined by the
// longer marubozu pattern over bars startIdx through endIdx.
//
// A two-candle pattern of two opposite-color marubozu (long body, very short
// shadows on both ends) separated by a gap. A strong directional/reversal
// signal whose bull/bear bias is set by the longer of the two marubozu.
//
// Formula and more info at https://ta-lib.org/functions/cdlkickingbylength.
//
